from pathlib import Path
import json,html,csv
from PIL import Image,ImageOps,ImageDraw

base=Path(__file__).resolve().parents[1]
records=json.loads((base/'work/source-manifest.json').read_text(encoding='utf-8'))
byid={r['id']:r for r in records}
ids=['38-12','38-17','38-24','38-27','38-31','38-34','38-35','38-36','04-03','04-13']
labels=['المطبخ','غرفة النوم','تسريحة ومرآة','بوفيه أسود وذهبي','مجموعة السفرة','كرسي سفرة','الاستقبال','وحدة التلفزيون','كرسي مستقل — بديل','ترابيزة قهوة — بديل']
sheet=Image.new('RGB',(1600,900),(243,240,232)); d=ImageDraw.Draw(sheet)
for i,identity in enumerate(ids):
    r=byid[identity]
    with Image.open(r['source']) as im:
        thumb=ImageOps.contain(ImageOps.exif_transpose(im).convert('RGB'),(310,400))
        x=(i%5)*320;y=(i//5)*450
        sheet.paste(thumb,(x+(310-thumb.width)//2,y+(400-thumb.height)//2))
    d.text((x+8,y+407),identity+' '+r['file'][:25],fill='black')
sheet.save(base/'work/sources/selected-sources.jpg',quality=92)
out=[]
for identity,label in zip(ids,labels):
    r=byid[identity]
    out.append(dict(id=identity,role=label,source=r['source'],catalog_folder=r['folder'],file=r['file'],width=r['width'],height=r['height'],owner='VILL Studio source archive; confirm for release',rights='Source supplied in brand archive; release/people clearance pending',state='PREVIS source selection',destination='Professional project photography / product edit; original ratio',variants='One primary edit per selected source; optional 4:5 after crop review'))
(base/'work/asset-manifest.json').write_text(json.dumps(out,ensure_ascii=False,indent=2),encoding='utf-8')
table=''.join(f'<tr><td>{r["id"]}</td><td>{html.escape(r["role"])}</td><td dir="ltr">{html.escape(r["file"])}</td><td>{r["width"]} × {r["height"]}</td></tr>' for r in out)
cards=[('38','الاختيار المفضل','تشطيب وفرش متناسقان: مطبخ، غرفة نوم، تسريحة، بوفيه، سفرة وكراسي واستقبال. نعتمد مجموعة 7 سبتمبر؛ صور الأبواب في يوليو ولقطة أغسطس خارج الترشيح الأساسي.'),('04','بديل قطع الأثاث','أوضح بديل للكرسي الأزرق/الرمادي بإطار ذهبي وترابيزة القهوة الهندسية. مجلد مختلط زمنيًا؛ نستبعد الكنبة وغرفة الأطفال المضافتين لاحقًا.'),('17','بديل المشروع السكني','مطبخ مفتوح، سفرة، صالون وغرفة أطفال. صور مستخدمة وازدحام وانعكاسات أشخاص. آخر صورتين لمحل، خارج المجموعة السكنية.')]
sections=''.join(f'<section><p class="tag">{tag}</p><h2>مجموعة {num}</h2><p>{desc}</p><a href="candidate-{num}.jpg"><img src="candidate-{num}.jpg" alt="كل الصور في مجموعة {num}"></a></section>' for num,tag,desc in cards)
doc='''<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>VILL Studio — ورقة اختيار الصور</title><style>body{margin:0;background:#eee9de;color:#17343c;font-family:Arial,sans-serif;line-height:1.8}main{max-width:1100px;margin:auto;padding:42px 24px}header{padding:28px;background:#01304a;color:#fff;border-radius:18px}h1{font-size:clamp(25px,4vw,44px);line-height:1.35;margin:8px 0}h2{margin:0}section{background:#fffdf7;border-radius:16px;padding:24px;margin:24px 0}img{display:block;width:100%;height:auto;margin-top:20px}table{width:100%;border-collapse:collapse;font-size:14px}td,th{padding:10px;border-bottom:1px solid #ded9cc;text-align:start}.tag{color:#a64a16;font-weight:bold}header .tag{color:#ffbc7e}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}small{color:#596b70}a{color:#075a78}@media(max-width:650px){.grid{grid-template-columns:1fr}section{padding:16px}table{font-size:11px}td{padding:6px}}</style><main><header><p class="tag">VILL Studio · 13 أكتوبر 2026 · ورقة عمل 02</p><h1>مشروع كامل، ثم تفاصيل الأثاث</h1><p>ترشيح مجموعة 38 كبداية: صور تشطيب وفرش حقيقية من الفوتوبانك. هذه ورقة اختيار ومراجعة؛ الصور المعروضة هي الأصول قبل التحسين.</p></header><section><h2>المجموعة المقترحة للتنفيذ</h2><p>8 مصادر من مجموعة 38 تغطي المشروع والقطع، مع بديلين من مجموعة 04 للكرسي والترابيزة. لا نخلط البدائل داخل قصة مشروع 38. البوفيه الأسود ظاهر بوضوح؛ الشوكيس الزجاجي غير مؤكد ضمن هذه المجموعات.</p><a href="selected-sources.jpg"><img src="selected-sources.jpg" alt="عشرة مصادر مختارة مع أرقام مرجعية"></a><div style="overflow:auto"><table><tr><th>المرجع</th><th>الاستخدام</th><th>ملف الأصل</th><th>الأبعاد</th></tr>'''+table+'''</table></div></section><div class="grid"><section><h2>اليوم الأول</h2><p>تأكيد المجموعة ومطابقة الصور لنفس المشروع. اختيار 4 لقطات مساحات و3 قطع: السفرة والكرسي والبوفيه. عمل بطاقة لكل قطعة من زواياها الأصلية، وتحديد الخطوط والأجزاء والخامات التي يجب تثبيتها.</p></section><section><h2>اليوم الثاني</h2><p>تحسين الضوء أولًا على صورة حقيقية واحدة، ومراجعتها بجوار الأصل. بعد تثبيت النتيجة نكمل الباقي، ثم خلفية الاستوديو للقطع كمرحلة مستقلة. مراجعة هندسة القطع والألوان والظلال؛ ثلاث جولات كحد أقصى لكل مرحلة.</p></section></div><section><h2>طريقة التنفيذ التي نجحت سابقًا</h2><p>نبدأ بتعديل الصورة الأصلية؛ نحافظ على شكل القطعة وزاوية الكاميرا. لا نغيّر القطعة والديكور في خطوة واحدة. نؤكد الملف المقبول بجوار الأصل قبل الانتقال لخلفية الاستوديو. أي إعادة تصوير مولدة تُعامل كرندر داخليًا، وتحتاج مراجعة فعلية قبل اعتبارها جاهزة.</p><p>موعد اليومين مقترح بعد تأكيد الاختيار؛ ليس موعد تسليم مثبتًا. المقاس النهائي واتجاه الصورة المرجعي يتحددان قبل الرندر. الأصول والوجوه الظاهرة تحتاج تأكيد صلاحية الاستخدام قبل النشر.</p></section>'''+sections+'''<small>الفحص البصري: 108 صور أصلية عبر ثلاث لوحات، ثم عشرة مصادر مختارة. مجموعات الفوتوبانك آلية؛ لا تثبت وحدها أن كل الملفات تخص عقدًا واحدًا. الملفات الأصلية محفوظة في مكانها؛ لا صور احترافية نهائية أنتجت في هذه الجولة.</small></main></html>'''
(base/'work/sources/worksheet.html').write_text(doc,encoding='utf-8')
lines=['# Source selection — worksheet 02','', 'State: PREVIS · Readiness: NOT_READY · Date: 2026-10-13','', '## Inspected evidence','108 original thumbnails visually inspected: 04=35; 17=37; 38=36. Contact sheets generated by read-only Pillow from original bank files. Existing CLIP catalog used; no re-embedding or new model inference.','', 'Preferred candidate: 38, specifically coherent 2019-09-07 sequence. Same folder contains earlier July door pictures and August room image: excluded from project primary selection. Grouping alone is not proof of one project.','04: strong grey/navy tufted armchairs with gold perimeter frames; black polygonal coffee table and gold wire base. Later 2020 sofa and 2019 bunk-bed shots are excluded.','17: kitchen/living/dining/children bedroom visible, but highly occupied and cluttered; final 2019-12 shop pictures excluded.','Showcase/display cabinet: not confirmed in these inspected sources. Black/gold sideboard is labelled sideboard, never showcase.','', '## Selected assets']
